            Set.of(product("P1", 10), product("P2", 20))
    );
    Subset s2 = new Subset(
            Set.of(product("P3", 30), product("P4", 40))
    );
    Coupon c1 = coupon("C1", 50, 0);
    Coupon c2 = coupon("C2", 75, 50);
    Combination combination = new Combination(List.of(s1, s2));

    List<PotentialOrder> result = optimizer.generateAllPotentialOrders(List.of(c1, c2), List.of(combination));

    // 1st subset: 3 options (no coupon, c1, c2)
    // 2nd subset: for each previous, again 3 options but coupons can't repeat
    // total = 9 - duplicates (where same coupon reused) = 7
    assertThat(result).hasSize(7);
}

@Getter
@Setter
@Schema(description = "A helper class containing a Subset with an assigned coupon, and the final sum including the discount")
public class PotentialCart {
    private Subset subset;
    private Coupon coupon;
    @Schema(description = "The total sum of the potential cart with discount applied")
    private BigDecimal totalPrice = BigDecimal.ZERO;
}

public PotentialCart(Subset subset) {
    this.subset = subset;
    calculateTotalPrice();
}

public PotentialCart(Subset subset, Coupon coupon) {
    this.subset = subset;
    this.coupon = coupon;
    calculateTotalPrice();
}

private void calculateTotalPrice() {
    if (coupon == null || subset.getTotalPrice().compareTo(coupon.getMinPrice()) < 0) totalPrice = subset.getTotalPrice();
    else {
        BigDecimal proposedDiscount = subset.getTotalPrice().multiply(BigDecimal.valueOf(coupon.getPercentDiscount() / 100.0));
        BigDecimal discount = proposedDiscount.compareTo(coupon.getMaxDiscount()) <= 0 ? proposedDiscount : coupon.getMaxDiscount();
        totalPrice = subset.getTotalPrice().subtract(discount);
    }
}

@Setter
@Getter
@Schema(description = "List of potential carts with an assigned coupons containing all products from the initial product list ")
public class PotentialOrder {
    private List<PotentialCart> potentialCarts;
    @Schema(description = "The total sum of the order")
    private BigDecimal totalPrice = BigDecimal.ZERO;
}

public PotentialOrder(List<PotentialCart> potentialCarts) {
    this.potentialCarts = potentialCarts;
    calculateTotalPrice();
}

private void calculateTotalPrice() {
    totalPrice = potentialCarts.stream()
            .map(PotentialCart::getTotalPrice)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
}

public List<Coupon> findAllUsedCoupons() {
    List<Coupon> usedCoupons = new ArrayList<>();

    potentialCarts.forEach(potentialCart -> usedCoupons.add(potentialCart.getCoupon()));

    return usedCoupons;
}

